def main() -> None:
    uz_path = ROOT / "locales" / "uz.json"
    uz = json.loads(uz_path.read_text(encoding="utf-8"))
    phrases = uz.get("phrases") or {}
    for k, v in MORE.items():
        phrases[k] = v
    # also map keys that are still Cyrillic in values
    still = 0
    for k, v in list(phrases.items()):
        if re.search(r"[А-Яа-яЁё]", v) and k in MORE:
            phrases[k] = MORE[k]
        if re.search(r"[А-Яа-яЁё]", phrases[k]):
            still += 1
    uz["phrases"] = phrases
    uz_path.write_text(json.dumps(uz, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("merged", len(MORE), "still_cyrillic_values", still)


if __name__ == "__main__":
    main()
